    added(state, action: PayloadAction<string>) {
      state.push({ text: action.payload, done: false })
    },
  },
})
export const store = configureStore({ reducer: { todos: todosSlice.reducer } })
export type RootState = ReturnType<typeof store.getState>
export const useAppSelector: TypedUseSelectorHook<RootState> = useSelector

export const add = createAction('[Todos] Add', props<{ text: string }>());
export const todosReducer = createReducer(
  [] as Todo[],
  on(add, (state, { text }) => [...state, { text, done: false }]),
);
